{"type": "function", "name": "search_products", "parameters": {"type": "object", "properties": {"query": {"type": "string", "description": "Search the catalog by query, category, or price range.", "parameters": {"type": "object", "properties": {"query": {"type": "string", "description": "The query to search for.", "default": "phone"}, "category": {"type": "string", "description": "The category of the product to search in.", "default": "electronics"}, "max_price": {"type": "number", "description": "The maximum price to filter results by.", "default": 1000}}}, "required": ["query"]}}
