{"type": "function", "name": "add_to_cart", "description": "Add a product to the cart.", "parameters": {"type": "object", "properties": {"asin": {"type": "string", "description": "The ASIN of the product to add to the cart."}, "quantity": {"type": "integer", "description": "The quantity of the product to add to the cart."}}}, "required": ["asin"]}}
{"type": "function", "name": "place_order", "description": "Check out the current cart to a ship-to address.", "parameters": {"type": "object", "properties": {"address_id": {"type": "string", "description": "The address ID to ship to."}, "speed": {"type": "string", "enum": ["standard", "two_day", "same_day"], "description": "The delivery speed."}}}, "required": ["address_id"]}}
