{"type": "function", "name": "track_shipment", "description": "Track a shipment by order id.", "parameters": {"type": "object", "properties": {"order_id": {"type": "string", "description": "The order ID to track."}}}, "required": ["order_id"]}}
{"type": "function", "name": "return_item", "description": "Start a return for an item on an order.", "parameters": {"type": "object", "properties": {"order_id": {"type": "string", "description": "The order ID to return an item from."}, "asin": {"type": "string", "description": "The ASIN of the item to return."}, "reason": {"type": "string", "description": "The reason for the return."}}}, "required": ["order_id", "asin"]}}
{"type": "function

